INSERT INTO creatures (slug, name, category, system, playable, alignment, attributes, hp, sdc, mdc, ppe, isp, pools_note, ar, horror_factor, combat, bonuses_note, skills_note, natural_abilities, magic, psionics, size, weight, life_span, habitat, allies, enemies, occ_note, description, source_book) VALUES
('xiticix-killer', 'Xiticix Killer', 'mutant', 'rifts', 0, 'Animal; effectively anarchist by human perception', '{"IQ":"2D4+3","ME":"2D6+4","MA":"2D6","PS":"3D6+14","PP":"3D6+10","PE":"3D6+6","PB":"2D6","Spd":"6D6+12"}', NULL, NULL, 'PEx3+1D6x10', '6D6', NULL, 'Hit Points and S.D.C.: not applicable, a mega-damage being. M.D.C. printed as P.E. attribute number x3 +1D6x10. P.S. and P.E. are supernatural. I.Q. is high animal intelligence. Spd is on the ground or climbing. P.P.E. printed as an average of 6D6. Recovers 2D6 M.D.C. per day. The small left arm tentacle has 10 M.D.C. of its own. The young have roughly half the M.D.C., attacks, bonuses and skill level of an adult and lack the bionic limbs and energy weapon. No Horror Factor is printed.', NULL, NULL, '{"attacks":7,"initiative":4,"strike":3,"parry":3,"dodge":4,"roll":3}', 'Bonuses are in addition to attribute bonuses. +3 to save vs poison and disease, +10 to save vs Horror Factor. Magic energy attacks (fire ball, lightning and the like) do half damage, other magic has full effect; unaffected by ley line storms. Right arm tentacle, tail and kick each do supernatural P.S. damage (no figure printed); the right arm tentacle and the tail reach 16 feet (4.9 m). Head horns: a roll of 5 or higher is a penetrating blow that holes a Xiticix exoskeleton or body armor. Claw hand: a slash, stab or power punch doing 12 or more damage holes the armor the same way; a power punch does double damage. Left arm tentacle inside a victim: three independent attacks per melee round that cannot be avoided, the victim loses initiative and half his melee attacks; pulling it out causes 6D6 damage; severing it needs a called shot of 19 without modifiers or a natural 20, and the severed portion thrashes for one more attack doing 4D6 M.D. Energy bolts: two per melee round, each counting as one melee attack, at most eight blasts per 20 minutes. Never uses weapons other than the built-in bionic ones. The standard attack usually kills a Xiticix in two melee rounds or leaves it dying within 1D4 melee rounds. Keeps fighting unless reduced to 30% or less of its M.D.C.', 'Acrobatics 80%, Climb 95%/90%, Swim 65%, Prowl 60% +2% per level, Identify scents 46% +2% per level (+30% to recognize Xiticix scent), Track Xiticix by scent 70% +2% per level (other scents at half). R.C.C. Skills: Detect Ambush (+5%), Detect Concealment (+5%), Land Navigation (+15%), Wilderness Survival (+20%). R.C.C. Related Skills: none. Secondary Skills: only if exposed to the player characters, four, plus two more per every other level exposed to them, at base skill level with no bonuses, from Domestic (any), Espionage (Tracking only), Military (Camouflage only), Physical (Running, Wrestling only), Technical (understand but not speak any language, or basic lores), Wilderness (Identify Plants and Track Animals only).', 'Supernatural strength and endurance with a mega-damage hide. Keen hearing and hawk-like eyesight that picks out a flying Xiticix at two miles (3.2 km). Holds its breath for 1D4+2 minutes. Standing leaps of 25 feet (7.6 m) up or 50 feet (15.2 m) across, half again as far with a run-up, and it can sprint flat out for an hour before slowing by 30%. Prehensile tail and toes, double jointed, ambidextrous. Regrows tentacles, tail, tongue and quills (not legs or upper arms) in about 2D4+10 days. Skin shifts between snow white in winter and light grey in summer.', 'None.', 'None. The energy bolts of the right arm are treated as the equivalent of psionic energy blasts.', 'Average 14 feet (4.3 m); 12 to 14 feet (3.6 to 4.2 m) fully erect, usually hunched low', '400 pounds (180 kg)', 'Should live to about 50, but averages 2-8 years; 1D4 offspring, physically mature at 10 months and sexually mature at 16 months', 'Xiticix territory in the northern woodlands, in the trees and on the hives; about 7200 believed alive (29,820 lab-made over seven years plus an estimated 4500 free born)', 'None; the Coalition''s Lone Star Complex made it and officially denies any knowledge of it', 'The Xiticix, the only thing it hunts and the only thing it can feed on; it fights other creatures only in self-defense', 'No player-character note is printed, but the book does print an experience ladder for it (shared with the Psi-X Alien, p.175: level 2 at 2,201, level 15 at 425,001-525,000). Cybernetics: two bionic limbs, the left forearm claw housing and the right arm energy weapon. Standard equipment and money: none. No Identification Coding; most people take it for a D-bee.', 'A top secret gene-spliced hunter that Doctor Bradford''s team at Lone Star spent six years building on Emperor Prosek''s order, made to look alien so that neither the Xiticix nor the Coalition''s rivals would trace it to the CS. It is a solitary, hairless, bipedal ambusher with a bladed claw and a gut-shredding tentacle on the left arm, a long grappling tentacle and energy weapon on the right, nose horns and a crest of quills. It can eat nothing but Xiticix, so it starves if they ever vanish.', 'Rifts World Book 13: Lone Star p.91-93');
INSERT INTO notable_npcs (slug, name, real_name, title, system, race, occ, level, alignment, age, height, weight, attributes, hp, sdc, mdc, ppe, isp, ar, horror_factor, combat, bonuses_note, skills, skills_note, natural_abilities, magic, psionics, super_powers, cybernetics, weapons_and_equipment, money, disposition, allies, enemies, description, source_book) VALUES
('desmond-bradford', 'Desmond Bradford', 'Desmond Bradford', 'Administrator of the Lone Star Complex; Doctor of Genetic Engineering and Cybernetics; Head of the Genetics Engineering Division (GED) at Lone Star', 'rifts', 'Human', '20th level Cyber-Doc and Genetic Engineer, 10th level Administrator', 20, 'Aberrant', '69; looks to be in his late thirties', '6 feet, 2 inches (1.9 m)', '210 lbs. (95 kg)', '{"IQ":27,"ME":21,"MA":18,"PS":19,"PP":15,"PE":14,"PB":11,"Spd":15}', 71, 20, NULL, 15, NULL, NULL, 14, '{"attacks":7,"initiative":2,"strike":2,"parry":4,"dodge":4,"pull":3,"roll":3,"damage":11}', 'Printed as Horror/Awe Factor 14. Damage bonus is S.D.C. damage. +3 to pull/roll with punch, fall or impact; kick attack (1D6 damage); critical strike on 18-20; judo-style body throw/flip; paired weapons.', '[{"name":"Language: American","pct":98},{"name":"Language: Spanish","pct":98},{"name":"Language: Gobblely","pct":98},{"name":"Literacy: American","pct":98},{"name":"Literacy: Spanish","pct":98},{"name":"Swimming","pct":98},{"name":"S.C.U.B.A.","pct":98},{"name":"Pilot hover craft (ground)","pct":98},{"name":"Computer operation","pct":98},{"name":"Computer programming","pct":98},{"name":"Computer hacking","pct":98},{"name":"Radio: basic","pct":98}]', 'Knows all medical and science skills at 98%. At approximately 85%: interrogation techniques, intelligence, streetwise, find contraband, palming, computer repair, horsemanship, land navigation, wilderness survival. W.P. knife/surgeon skill at 20th level, W.P. energy pistol 10th level, W.P. energy rifle 6th level. Hand to Hand: Expert, 10th level.', NULL, 'None.', 'None.', NULL, 'Clock calendar; gyro-compass; universal headjack and ear implant', 'Access to virtually anything he needs from the CS Government and Military; highest security clearance, all levels and facilities of the Lone Star Complex. Favorite weapons: laser scalpels, vibro-knives, Dog Boy Vambraces with two claws and/or double sabers, Electro-Stun hand prod and spear, plus a variety of drugs and implants (used to control others). Wears heavy, old-style Dead Boy armor in the field. Usually carries or has nearby: latest hand-held computer, portable language translator, pocket laser distancer, PDD audio recorder and player, medical bag with all standard first-aid/doctor equipment, laser scalpel, RMK Knitter nano-bots, IRMSS surgeon nano-bots, compu-drug dispenser, small set of lock picking tools. Access to all other medical, cybernetic, bionic, M.O.M. and laboratory equipment and facilities.', 'As Administrator: access to billions of credits for research and hundreds of trillions of credits worth of equipment and facilities. Personal: four million in universal credits; 4D6x one million credits worth of pre-Rifts artifacts; over 50 million credits worth of genetics, medical and lab equipment at an underground hideout in Ciudad Juarez; caches of basic travel and medical equipment (vehicle, armor, weapons, medical bag) and debit cards of 100,000 universal credits at a half dozen secret locations in the State of Lone Star.', 'A megalomaniac who thinks himself a deity among lesser men and has no patience for slow or timid minds. Calculating and methodical rather than reckless; he drives his staff mercilessly and removes anyone who gets in the way of his research.', 'Emperor Karl Prosek (old friend of 40 years, his only friend); General Loni Kashbrook (cordial working relationship); Major Winston Claval; elite team of 112 scientists, 50 assistants, about 130 mutant creations, 20 Crazies and 30 Kill Hounds held by threats, implants and personality modifiers', 'Colonel Joseph Prosek II (investigating him in secret); Brigadier General Ivan Kalpov (mutual dislike); General Cabot and most military leaders fear him', 'Creator of the Dog Boys and absolute master of the Lone Star Complex, which he brought back on line for the Coalition. Behind the sanctioned work he runs a hidden research level where forbidden experiments on humans and D-bees produced the Psi-X Aliens and worse, and he has murdered CS investigators to keep it secret.', 'Rifts World Book 13: Lone Star p.100-107'),
('general-loni-kashbrook', 'General Loni Kashbrook', 'Loni Kashbrook (no middle name)', 'Head of Lone Star (the State) Operations & Administration; 3-Bar General', 'rifts', 'Human', '12th level Military Specialist; 3-Bar General', 12, 'Aberrant', '48; looks to be in her mid to late thirties; physically fit', '6 feet (1.8 m)', '150 lbs. (67.5 kg)', '{"IQ":17,"ME":21,"MA":23,"PS":21,"PP":14,"PE":14,"PB":18,"Spd":19}', 57, 32, NULL, 6, NULL, NULL, 12, '{"attacks":5,"initiative":2,"strike":2,"parry":5,"dodge":5,"pull":2,"roll":2,"damage":9}', 'Printed as Horror/Awe Factor 12. Damage bonus is S.D.C. damage. +2 to pull/roll with punch, fall or impact; kick attack (1D6 damage); critical strike on 18-20; judo-style body throw/flip; paired weapons; +3 to save vs psionic attack; 40% to charm and impress; 75% to evoke a feeling of trust.', '[{"name":"Language: American","pct":98},{"name":"Language: Spanish","pct":98},{"name":"Literacy: American","pct":98},{"name":"Literacy: Spanish","pct":98},{"name":"Detect ambush","pct":98},{"name":"Detect concealment","pct":98},{"name":"Intelligence","pct":98},{"name":"Interrogation techniques","pct":98},{"name":"Wilderness survival","pct":98},{"name":"Camouflage","pct":98},{"name":"Military etiquette","pct":98},{"name":"Military fortification","pct":98},{"name":"Recognize weapon quality","pct":98},{"name":"Pilot: jet pack","pct":98},{"name":"Pilot: robots combat elite","pct":98},{"name":"Pilot: hover vehicles","pct":98},{"name":"Computer operation","pct":98},{"name":"Radio: basic","pct":98},{"name":"Demon and monster lore","pct":73},{"name":"D-Bee lore","pct":73},{"name":"Prowl","pct":60},{"name":"Streetwise","pct":59}]', 'W.P. energy pistol and W.P. energy rifle at 12th level proficiency; W.P. automatic pistol at 7th level. Hand to Hand: Expert, 12th level. Loves hovercycles.', NULL, 'None.', 'None.', NULL, 'Clock calendar; gyro-compass; radiation detector; universal headjack and ear implant', 'Access to virtually any military weapons and equipment she needs; highest security clearance, all levels of Chi-Town and most (70%) of the levels at the Lone Star Complex. Favorite weapons: old C-14 Fire Breather assault rifle, new CP-50 Dragonfire assault rifle, CP-30 laser pistol. Wears a variety of old and new style Dead Boy armor in the field. Standard military gear, hand-held computer, portable language translator, pocket laser distancer.', 'As Head of Lone Star Military Operations: access to billions of credits worth of military equipment and troops. Personal: 1.2 million in savings and a military pension.', 'A confident, decisive career officer who leads from the front, negotiates well and never bluffs. Fair and caring toward Coalition citizens and her troops, yet a convinced human supremacist who will wipe out a nonhuman settlement without remorse.', 'Emperor Karl Prosek and Joseph Prosek II; Desmond Bradford (mutual respect, though she keeps out of Complex affairs); the Wolf Division (6000 troops, 98% Dog Boys), Coyote Brigade and Pecos Hunter Company under her command', 'Pecos Bandits (Warlord Grange and his Pecos Riders); Juicers; Tolkeen death squads; regards Colonel Collins and Kalpov''s other henchmen as dangerous fanatics and would retire Kalpov if she could', 'Member of the Executive Counsel and High Command who took over a collapsing northern Lone Star command twelve years ago and turned it into a secure, expanding Coalition territory. A 28-year veteran prized for strategy and logistics, she commands from Wichita Falls and wins her objectives with fewer losses than any other CS general.', 'Rifts World Book 13: Lone Star p.107-110'),
('brigadier-general-ivan-kalpov', 'Brigadier General Ivan Kalpov', 'Ivan Thomas Kalpov', 'Brigadier General; commander of the military defenses and forces at the Lone Star Complex', 'rifts', 'Human (partial reconstructed cyborg)', '14th level Military Specialist; Brig. General', 14, 'Aberrant', '54; looks his age', '5 feet, 10 inches (1.75 m)', '200 lbs. (90 kg)', '{"IQ":15,"ME":19,"MA":18,"PS":22,"PP":20,"PE":14,"PB":8,"Spd":44}', 72, 29, NULL, 4, NULL, NULL, 12, '{"attacks":7,"initiative":3,"strike":5,"parry":10,"dodge":10,"pull":3,"roll":5,"damage":11}', 'Printed as Horror/Awe Factor 12. P.S. 22, P.P. 20 and Spd. 44 (30 mph/48 km) are bionic. Damage bonus is S.D.C. damage. +3 to pull punch; +5 to roll with punch, fall or impact; kick attack (1D6 damage); critical strike on 18-20; judo-style body throw/flip; paired weapons; +2 to save vs psionic attack; +7 to save vs horror factor; 55% to evoke a feeling of trust or intimidation.', '[{"name":"Language: American","pct":98},{"name":"Language: Spanish","pct":98},{"name":"Language: Gobblely","pct":98},{"name":"Literacy: American","pct":98},{"name":"Detect ambush","pct":98},{"name":"Detect concealment","pct":98},{"name":"Intelligence","pct":98},{"name":"Interrogation techniques","pct":98},{"name":"Find contraband","pct":98},{"name":"Trap construction","pct":98},{"name":"Military etiquette","pct":98},{"name":"Recognize weapon quality","pct":98},{"name":"Swimming","pct":98},{"name":"Climbing","pct":98},{"name":"Track (humanoids)","pct":98},{"name":"Wilderness survival","pct":98},{"name":"Pilot: tanks and APCs","pct":98},{"name":"Pilot: robots combat elite","pct":98},{"name":"Pilot: hover vehicles","pct":98},{"name":"Computer operation","pct":98},{"name":"Radio: basic","pct":98},{"name":"Demon and monster lore","pct":80},{"name":"Disguise","pct":60},{"name":"Streetwise","pct":64}]', 'W.P. energy pistol and W.P. energy rifle at 14th level proficiency; W.P. heavy energy weapons at 7th level. Hand to Hand: Martial Arts, boxing and wrestling, all at 14th level proficiency.', NULL, 'None.', 'None.', NULL, 'Partial conversion ''Borg, 65% machine. Clock calendar; gyro-compass; radiation detector; universal headjack and ear implant with ultra-ear and sound filtration system; built-in radio receiver and transmitter; loudspeaker; built-in language translator; modulating voice synthesizer; bionic lung with gas filter and oxygen storage cell; multi-optics eye; bionic legs; bionic arms. Right arm: retractable vibro-blade (2D6 M.D.) and garrote wrist wire; right hand: fingerjack and utility finger laser (1D6 or 3D6 S.D.C.). Left arm: concealed arm laser (1D6 M.D.); left hand: finger camera and E-Clip port. Each leg has one medium-sized secret compartment, usually holding a half dozen grenades, a vibro-blade and other small items.', 'Access to virtually any military weapons and equipment he needs. High security clearance: all military levels and facilities at the Lone Star Complex, but only low level clearance at GED and other science/research areas. Favors heavy energy weapons and rail guns. Wears CA-6C cyborg body armor (200 M.D.C.) unless in disguise or incognito. Standard military gear, a vibro-saber, hand-held computer, portable language translator, pocket laser distancer.', 'Access to billions of credits worth of military equipment and troops. Personal: 500,000 in savings and a military pension.', 'A hard, stubborn old soldier who relishes a fight and buys his victories with heavy casualties among his own men. Embittered at being passed over, he overreacts to any threat, shows nonhumans and magic users no mercy, and is savage in interrogations.', 'Colonel Roger Collins (protege and confidant); Colonel Buck Murphy (liked, though thought a bit green); under his command two companies (320) of Coalition Cyborgs, a company (160) of CS Juicers, RPA pilots, Special Forces and thousands of grunts and Dog Boys', 'Desmond Bradford (mutual dislike, they stay out of each other''s way); sorcerers above all others; nonhumans; resents General Kashbrook''s command as too conservative and soft, though he respects her', 'Thirty-five-year veteran from a military family and the Coalition''s third most decorated officer, nicknamed Old Blood & Circuits for the many body parts he has had replaced with bionics. He guards the Lone Star Complex, would rather be leading an offensive, and sometimes joins patrols in disguise to judge his troops.', 'Rifts World Book 13: Lone Star p.110-114'),
('colonel-roger-collins', 'Colonel Roger Collins', 'Roger Bertram Collins', 'Colonel; head of Intelligence (Intelligence Corps) at the Lone Star Complex', 'rifts', 'Human', '10th level Military Specialist; Colonel', 10, 'Miscreant; but steadfastly loyal to Brig. Gen. Kalpov and the Coalition States', '39', '5 feet, 9 inches (1.7 m)', '160 lbs. (72 kg)', '{"IQ":15,"ME":20,"MA":9,"PS":20,"PP":18,"PE":17,"PB":9,"Spd":17}', 62, 42, NULL, 5, 73, NULL, 10, '{"attacks":7,"initiative":1,"strike":4,"parry":7,"dodge":7,"pull":3,"roll":5,"damage":9}', 'Printed as Horror/Awe Factor 10. Damage bonus is S.D.C. damage. +3 to pull punch; +5 to roll with punch, fall or impact; kick attack (1D6 damage); critical strike on 19-20; knockout on 17-20; +3 to save vs psionic attack; +1 to save vs magic and poison/drugs; +5 to save vs horror factor.', '[{"name":"Language: American","pct":98},{"name":"Literacy: American","pct":98},{"name":"Interrogation techniques","pct":65},{"name":"Find contraband","pct":72},{"name":"Radio: basic","pct":98},{"name":"Radio: scramblers","pct":80},{"name":"Electronic countermeasures","pct":85},{"name":"Surveillance systems","pct":75},{"name":"Optic systems","pct":75},{"name":"TV/video","pct":61},{"name":"Cryptography","pct":60},{"name":"Military etiquette","pct":95},{"name":"Computer operation","pct":98},{"name":"Streetwise","pct":48}]', 'Knows all espionage skills at the base skill +45% (averaging 65-85%). Imitate voices/impersonation 74%/54%. Pilot: robots combat elite and pilot: hovercraft (no % printed). W.P. energy pistol, W.P. energy rifle, W.P. blunt and W.P. knife, all at 10th level. Hand to Hand: Assassin and boxing, all at 10th level.', NULL, 'None.', 'Minor psionic, 73 I.S.P.: sixth sense; object read', NULL, 'Clock calendar; gyro-compass; universal headjack and ear implant', 'Access to virtually all basic weapons, surveillance equipment, vehicles and other equipment, men and resources needed for his investigations; 320 Intelligence soldiers at the Lone Star Complex under his direct command. High security clearance: all military levels and facilities at the Lone Star Complex, but only low level clearance at GED and other science/research areas. Favorite weapons: Neuro-Mace, Electro-Stunner prod and spear, knives, high payload energy rifles. Wears any new style Dead Boy armor he feels is appropriate unless in disguise or incognito; often works undercover. Standard military gear, tracers, surveillance and recording equipment, hand-held computer, portable language translator, pocket laser distancer.', 'Access to millions of credits worth of military equipment and troops. Personal: 51,000 credits in official savings and a military pension; 250,000 universal credits secreted away (mainly blackmail and smuggling); 4D6x1000 credits worth of ancient artifacts hidden away at any given time; an emergency cache of weapons, armor, a hovercycle and 30,000 universal credits.', 'Cunning, vindictive and quick to rage, with a real gift for espionage and dirty work. A fanatic about the Coalition and the men he idolizes, he will frame, ruin or kill anyone he decides is a threat to them, and he cannot stand nonhumans, Dog Boys included.', 'Brigadier General Ivan Kalpov (mentor, obeys him without question); 320 Intelligence soldiers', 'Nonhumans; anyone who criticizes the CS, the Emperor or Kalpov; General Kashbrook regards him as a dangerous fanatic; Major Winston Claval despises him', 'Kalpov''s intelligence chief at the Lone Star Complex, seventeen years in service, who protects the reputations of his superiors through blackmail, torture, fabricated evidence and assassination. Killing him brands the killers as enemies of the Coalition and is likely to provoke Kalpov into bloody reprisals.', 'Rifts World Book 13: Lone Star p.114-115'),
('colonel-buck-murphy', 'Colonel Buck Murphy', 'Buck "Ironsides" Murphy', 'Colonel; Commander of the 93rd RPA Airborne Armored Cavalry', 'rifts', 'Human', '8th level RPA "Fly Boy" Ace; Colonel', 8, 'Unprincipled; loyal to the CS', '27', '6 feet (1.8 m)', '160 lbs. (72 kg)', '{"IQ":14,"ME":10,"MA":24,"PS":19,"PP":23,"PE":17,"PB":22,"Spd":16}', 62, 42, NULL, 8, 44, NULL, 10, '{"attacks":5,"initiative":5,"strike":5,"parry":8,"dodge":8,"pull":2,"roll":3,"damage":2}', 'Printed as Horror/Awe Factor 10. Damage bonus is S.D.C. damage. +2 to pull punch; +3 to roll with punch, fall or impact; kick attack (1D6 damage); judo-style throw (1D6); +3 to save vs psionic attack; +1 to save vs magic and poison/drugs; +5 to save vs horror factor. Under consideration for promotion to Brigadier General.', '[{"name":"Language: American","pct":98},{"name":"Literacy: American","pct":98},{"name":"Interrogation techniques","pct":65},{"name":"Find contraband","pct":72},{"name":"Radio: basic","pct":98},{"name":"Radio: scramblers","pct":80},{"name":"Electronic countermeasures","pct":85},{"name":"Surveillance systems","pct":75},{"name":"Optic systems","pct":75},{"name":"TV/video","pct":61},{"name":"Cryptography","pct":60},{"name":"Military etiquette","pct":95},{"name":"Computer operation","pct":98},{"name":"Streetwise","pct":48}]', 'AS PRINTED: the book''s Skills of Note paragraph for Murphy is word for word Colonel Collins''s (p.115), including ''all espionage skills at the base skill +45% (averaging 65-85%)'', imitate voices/impersonation 74%/54%, pilot: robots combat elite, pilot: hovercraft, and W.P. energy pistol, W.P. energy rifle, W.P. blunt and W.P. knife ''all at 10th level'' although he is 8th level; likely a printing error, no RPA pilot skills are listed. Hand to Hand: Basic and boxing, all at 8th level.', 'Uses either hand equally well, and his alertness and fast reactions are the source of his high initiative bonus.', 'None.', 'Minor psionic, 44 I.S.P.: sixth sense; presence sense. He is not aware he has these abilities; they manifest as hunches and feelings, especially in combat.', NULL, 'Clock calendar; gyro-compass; universal headjack and ear implant', 'Access to virtually all military weapons, equipment, all types of SAMAS, Skycycles, Death Wings and hovercycles, and select combat aircraft (jets and Death''s Head transports), plus select special equipment, men and resources; 320 Intelligence RPA Fly Boys under his command at the Lone Star Complex (as printed). High security clearance: all military levels and facilities at the Lone Star Complex, but only low level clearance at GED and other science/research areas. Favorite weapons: Special Forces Striker SAMAS, Super SAMAS, both Skycycles and their weapon systems. When not flying: light, old-style Dead Boy armor and rapid-fire, high payload laser weapons. Standard military gear, hand-held computer, portable language translator, pocket laser distancer.', 'Access to billions of credits worth of military equipment, SAMAS, aircraft and troops. Personal: 75,000 credits in savings and a military pension.', 'Charming, flamboyant and fearless in the air, but privately worn out and troubled by guilt over the men he loses and the helpless D-bees he is ordered to kill. He honors brave and honorable foes, sometimes letting them go, and is ruthless toward the wicked.', 'His officers and the men of the 93rd, who adore him; Brigadier General Kalpov likes him; Major Winston Claval considers him a living saint; works with both General Kashbrook and Kalpov', NULL, 'The Coalition''s most celebrated ace, a young colonel who earned the name Ironsides by driving a Xiticix swarm back through a Rift at the head of 160 SAMAS. His battalion is Lone Star''s sole field unit on active operations, flying reconnaissance, raids and rescue for both generals, while hiding burn-out and doubts about the Coalition''s cause.', 'Rifts World Book 13: Lone Star p.115-117'),
('major-winston-claval', 'Major Winston Claval', 'Winston Jason Claval', 'Head of Mutant Containment and Retrieval (MCR), Lone Star Complex', 'rifts', 'Human', '9th level CS Special Forces', 9, 'Aberrant; loyal to the CS and Doctor Bradford', '38', '6 feet (1.8 m)', '160 lbs. (72 kg)', '{"IQ":14,"ME":15,"MA":8,"PS":21,"PP":14,"PE":17,"PB":8,"Spd":18}', 62, 42, NULL, 8, NULL, NULL, 10, '{"attacks":7,"initiative":3,"strike":2,"parry":2,"dodge":2,"roll":3,"pull":6,"disarm":2,"damage":8}', 'Hand to Hand: Commando and boxing, 9th level; +1 on automatic dodge; damage bonus is S.D.C.; jump kick; Death Blow on 18-20; can go 48 hours without sleep; +6 to save vs possession, +2 vs mind control and illusions, +3 vs psionic attack, +1 vs poison and magic, +8 vs horror factor. Special abilities: resistant to horror factor and indomitable will. Current rank Major, a 20 year veteran.', '[{"name":"Language: American","pct":98},{"name":"Language: Spanish","pct":98},{"name":"Literacy: American","pct":65},{"name":"Radio: basic","pct":98},{"name":"Radio: scramblers","pct":85},{"name":"Prowl","pct":80},{"name":"Streetwise","pct":68},{"name":"Interrogation techniques","pct":75},{"name":"Find contraband","pct":75},{"name":"Intelligence","pct":74},{"name":"Escape artist","pct":85},{"name":"Land navigation","pct":78},{"name":"Wilderness survival","pct":85},{"name":"Lore: demons & monsters","pct":75},{"name":"Pilot hovercraft","pct":98},{"name":"Pilot jet pack","pct":84},{"name":"Pilot robots and power armor","pct":90}]', 'Literacy taught by Doctor Bradford. Robot combat elite: SAMAS. W.P. energy pistol, W.P. energy rifle, W.P. energy heavy, W.P. blunt and hand to hand: commando, all at 9th level. Loves hovercycles and jet packs.', NULL, 'None.', 'None.', NULL, 'Clock calendar; gyro-compass', 'Access to virtually all military weapons and equipment, all types of SAMAS, hovercycles and ground hover vehicles, plus select communications and surveillance gear. Commands one full company (160 troops: 100 Dog Boys, 40 humans, 20 other mutants); in a crisis could be given a full battalion (640 troops). Medium-High military clearance (answers to Brig. Gen. Kalpov); maximum clearance in GED and science/research areas (answers directly to Administrator Bradford). Favorites: Special Forces "Striker" SAMAS, Super SAMAS, Prowler, Rocket and Turbo hovercycles, rail guns, particle beam and plasma rifles, C-14 and CP-50 laser and grenade launcher rifles. Also standard military gear, hand-held computer, portable language translator, pocket laser distancer.', 'Access to millions of credits worth of military equipment, SAMAS and troops. Personal resources: 56,000 credits in savings and a military pension.', 'Cold, humorless and fearless, with a blunt street-tough manner. Methodical and tireless on the job, he kills marked targets without a second thought, distrusts most humans and would rather keep company with plain-spoken mutant animals.', 'Doctor Desmond Bradford (mutual trust; not controlled by implant or blackmail); his elite team the Quiet Hunters; likes General Kashbrook; reveres Colonel Murphy.', 'Dislikes Brigadier General Kalpov; despises Colonel Collins; hates mutant rats, including Mitch and Glitch.', 'A brutal, hard-drinking ex-Special Forces brawler who runs the unit that guards, transports, hunts and destroys the GED test subjects and runaway mutants. Eleven years in Special Forces, nine at Lone Star, six in his present post. He knows of Bradford''s illegal experiments and helps dispose of them; he would shield Bradford even against fellow officers and would loose the experimental mutants on anyone besieging GED.', 'Rifts World Book 13: Lone Star p.118-121'),
('thomas-bat-masterson', 'Thomas "Bat" Masterson', NULL, 'Quiet Hunter, member of the elite MCR Retrieval Team under Major Winston Claval', 'rifts', 'Human', '8th level Commando', 8, 'Aberrant', NULL, NULL, NULL, '{"IQ":14,"ME":17,"PS":20,"PP":18,"PE":13,"Spd":18}', 43, 39, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Apart from Claval himself, the sole human in the Quiet Hunters. One of the five members shown in the team illustration.', 'Rifts World Book 13: Lone Star p.119'),
('lt-rex-crackshot', 'Lt. Rex "Crackshot"', NULL, 'Lieutenant; Quiet Hunter, member of the elite MCR Retrieval Team under Major Winston Claval', 'rifts', 'Dog Boy (German Shepherd), male', '7th level Dog Boy', 7, 'Aberrant', NULL, NULL, NULL, '{"IQ":19,"PS":21,"PP":24,"Spd":28}', 41, 33, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'A German Shepherd Dog Boy of the Quiet Hunters, noted for extremely fast reflexes and for superb marksmanship with laser rifles of every kind.', 'Rifts World Book 13: Lone Star p.119'),
('sgt-robert-claw', 'Sgt. Robert "Claw"', NULL, 'Sergeant; Quiet Hunter, member of the elite MCR Retrieval Team under Major Winston Claval', 'rifts', 'Dog Boy (Bloodhound), male', '6th level K-9 Sniffer Dog Boy', 6, 'Miscreant', NULL, NULL, NULL, '{"IQ":9,"PS":20,"PE":24,"Spd":28}', 48, 30, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Skills of note (no percentages printed): track by scent, track by sight (humanoids and animals), hunt, fish, land navigation, wilderness survival, climbing and wrestling.', NULL, NULL, NULL, NULL, NULL, 'Favorite weapons are Vibro-Blade claws (no damage printed).', NULL, NULL, NULL, NULL, 'The Bloodhound "Sniffer" of the Quiet Hunters and the team''s tracker, who likes to fight with vibro-blade claws.', 'Rifts World Book 13: Lone Star p.119'),
('corp-lady-ann', 'Corp. "Lady" Ann', NULL, 'Corporal; Quiet Hunter, member of the elite MCR Retrieval Team under Major Winston Claval', 'rifts', 'Experimental feline mutant', '5th level CS scout/Ranger', 5, 'Anarchist', NULL, NULL, NULL, '{"IQ":13,"PS":24,"PP":20,"Spd":22}', 56, 48, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Lives for the excitement of the chase and is every bit as devoted to Claval as a Dog Boy would be.', NULL, NULL, 'An experimental mutant cat serving in the Quiet Hunters as a scout.', 'Rifts World Book 13: Lone Star p.119'),
('corp-big-bear', 'Corp. Big Bear', NULL, 'Corporal; Quiet Hunter, member of the elite MCR Retrieval Team under Major Winston Claval', 'rifts', 'Mutant bear with experimental bionics, male', 'Equal to a 3rd level CS Grunt', 3, 'Anarchist', NULL, '11 feet (3.3 m) fully erect', NULL, '{"IQ":7,"PS":34,"PP":11,"PE":30,"Spd":17}', 112, 93, NULL, NULL, NULL, NULL, 12, NULL, 'P.S. and P.E. are considered supernatural.', NULL, NULL, 'Strength and endurance count as supernatural, so his bare-handed blows inflict mega-damage. Usually stoops and moves on four legs.', NULL, NULL, NULL, 'Bionic eye with thermo-optics and telescopic vision; bionic lungs with gas filter and oxygen storage cell; bionic jaw (experimental) with built-in loudspeaker; built-in radio receiver and transmitter; modular weapon forearm with claw blades, ion blasters and Electro-Stun baton paws. Some systems are experimental.', 'Modular weapon forearm: claw blades, cannon-like ion blasters (60 shot payload each, recharging 1D6 blasts per hour), Electro-Stun baton paws (same jolt and damage as the ES spear).', NULL, NULL, NULL, NULL, 'A towering mutant bear in the Quiet Hunters, a successful test both of bear mutation and of fitting bionics to a mutant. The rats Mitch and Glitch are apt to manipulate him.', 'Rifts World Book 13: Lone Star p.119'),
('sgt-ears-rippley', 'Sgt. "Ears" Rippley', NULL, 'Sergeant; Quiet Hunter, member of the elite MCR Retrieval Team under Major Winston Claval', 'rifts', 'Dog Boy (German Shepherd/Collie mix), female', '5th level Dog Boy', 5, 'Unprincipled', NULL, NULL, NULL, '{"IQ":17,"PS":18,"PP":16,"PE":12,"Spd":32}', 36, 38, NULL, NULL, NULL, NULL, NULL, NULL, 'Rat Catcher mutant abnormality: +10% to tracking and prowling skills, +2 on initiative and +4 to damage when hunting rats and rodent-like creatures, including rodent-like D-bees.', NULL, NULL, 'A mutant quirk makes her a Rat Catcher, sharper and deadlier whenever her quarry is a rat or anything rodent-like.', NULL, NULL, NULL, NULL, NULL, NULL, 'Loyal and obedient.', NULL, NULL, 'A shepherd-collie cross Dog Boy of the Quiet Hunters; not among the five pictured in the team illustration.', 'Rifts World Book 13: Lone Star p.119'),
('corp-savage-mike', 'Corp. "Savage" Mike', NULL, 'Corporal; Quiet Hunter, member of the elite MCR Retrieval Team under Major Winston Claval', 'rifts', 'Dog Boy (Rottweiler)', '4th level Kill Hound', 4, 'Miscreant', NULL, NULL, NULL, '{"IQ":10,"PS":24,"PP":22,"Spd":30}', 47, 50, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'A Rottweiler Kill Hound of the Quiet Hunters; not among the five pictured in the team illustration.', 'Rifts World Book 13: Lone Star p.119'),
('corp-raphael-ralphy-boy', 'Corp. Raphael', NULL, 'Corporal; Quiet Hunter, member of the elite MCR Retrieval Team under Major Winston Claval; everybody calls him "Ralphy Boy"', 'rifts', 'Mutant wolf', '4th level Kill Hound', 4, 'Aberrant', NULL, NULL, NULL, '{"IQ":10,"PS":24,"PP":22,"PE":25,"Spd":36}', 44, 57, NULL, NULL, NULL, NULL, NULL, '{"attacks":5,"initiative":2}', NULL, NULL, 'Boxing and hand to hand: assassin. An excellent interrogator (no percentage printed).', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Easygoing and mild when off duty, but ferocious once a fight starts. He relishes the hunt and the kill, and enjoys frightening people with glares, bared teeth and threats.', NULL, NULL, 'A mutant wolf Kill Hound of the Quiet Hunters and the team''s interrogator; not among the five pictured in the team illustration.', 'Rifts World Book 13: Lone Star p.119'),
('mitch-mutant-rat', 'Mitch', NULL, 'Mutant rat attached to the Quiet Hunters under Major Claval for field observation as a potential CS espionage agent', 'rifts', 'Mutant rat', '2nd level thief with espionage training', 2, 'Miscreant; aggressive, cunning, clever, resourceful', NULL, NULL, NULL, '{"IQ":12,"PS":14,"PP":18,"PE":19,"Spd":24}', 24, 37, NULL, NULL, NULL, NULL, NULL, '{"attacks":4,"initiative":1}', NULL, NULL, 'Hand to hand: assassin. Detect ambush, camouflage, intelligence, palming, concealment, pick locks, pick pockets, prowl, climb and streetwise, all at 2nd level and each with a +10% skill bonus. Secretly learning to read and to operate a computer; both currently below base proficiency, about 30%.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'The schemer of the two rat brothers, good at laying traps and ambushes. A liar and thief with no loyalty to Claval or the team, behaving only until he can run.', 'His brother Glitch.', 'Major Claval neither trusts nor likes him.', 'One of two mutant rat brothers placed with Claval on trial as possible CS spies. They hope to go feral and found a rich, notorious outlaw gang; meanwhile they stir up trouble in the MCR, run extortion and con games on other mutants, sell information of mixed reliability, and would frame outsiders if caught.', 'Rifts World Book 13: Lone Star p.119-121'),
('glitch-mutant-rat', 'Glitch', NULL, 'Mutant rat attached to the Quiet Hunters under Major Claval for field observation as a potential CS espionage agent', 'rifts', 'Mutant rat', '2nd level thief with espionage training', 2, 'Miscreant; aggressive, cruel and mischievous', NULL, NULL, NULL, '{"IQ":5,"PS":16,"PP":22,"PE":15,"Spd":25}', 23, 26, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Dim-witted but very quick, and unafraid out of sheer belligerence. Obeys his brother blindly and is prone to bloodlust.', 'His brother Mitch.', 'Major Claval neither trusts nor likes him.', 'The slow-witted half of the two mutant rat brothers on trial with Claval as possible CS spies; shares Mitch''s disloyalty and his plan to go feral and lead an outlaw gang.', 'Rifts World Book 13: Lone Star p.119-121'),
('doctor-frederick-alexander', 'Doctor Frederick Alexander', 'Frederick Philip Alexander, Jr.', 'Captive GED scientist; surgeon, cyber-doc and genetic engineer', 'rifts', 'Human', '12th level Cyber-Doc and Genetic Engineer', 12, 'Scrupulous, although a human supremacist and loyal servant of the CS Military', '53', '5 feet, 8 inches (1.65 m)', '160 lbs. (72 kg)', '{"IQ":22,"ME":17,"MA":12,"PS":11,"PP":20,"PE":10,"PB":9,"Spd":10}', 62, 42, NULL, 7, NULL, NULL, NULL, '{"attacks":5,"strike":4,"parry":6,"dodge":6,"roll":2,"pull":2,"damage":2}', 'Hand to Hand: Basic, 6th level; damage bonus is S.D.C.; critical strike on 19-20; judo-style body throw/flip; +1 to save vs psionic attack. Horror/Awe Factor: not applicable.', '[{"name":"Language: American","pct":98},{"name":"Literacy: American","pct":98},{"name":"Criminal science & forensics","pct":98},{"name":"Medical doctor","pct":98},{"name":"M.D. in cybernetics","pct":98},{"name":"Pathology","pct":98},{"name":"Genetics (special)","pct":98},{"name":"Chemistry","pct":98},{"name":"Chemistry: analytical","pct":98},{"name":"Biology","pct":98},{"name":"Botany","pct":98},{"name":"Anthropology","pct":98},{"name":"Basic math","pct":98},{"name":"Advanced math","pct":98},{"name":"Computer operation","pct":98},{"name":"Computer programming","pct":98},{"name":"Pilot hovercraft (ground)","pct":98},{"name":"Radio: basic","pct":98}]', 'W.P. knife/surgeon skill at 12th level and W.P. energy pistol at 9th level.', NULL, 'None.', 'None.', NULL, 'Clock calendar; gyro-compass; universal headjack and ear implant. Also carries an explosive implant at the base of his skull, placed by his captors.', 'Only the genetic and lab facilities and basic medical equipment his keepers allow.', 'None; a captive whose basic needs are provided by Bradford and the others.', 'Worn down yet unbroken: a miserable prisoner given to depression and thoughts of suicide, sickened by the work forced on him. He loathes his three captor scientists enough to die if it would bring them down.', 'A potential ally to intruders or prisoners in the secret GED level, if he is sure they can destroy Bradford.', 'Doctors Bradford, Cunningham and Santiago (he does not know of Major Claval''s part). Cunningham watches him closely.', 'A gifted surgeon and geneticist held as Bradford''s slave in the top secret GED level, officially dead in an accident and unseen outdoors for 13 years (his stat block says 14). Kept in line by threats and the bomb in his skull, he works slowly and has quietly sabotaged several experiments; he fears he is next for the personality-altering implants. He can tell rescuers the level''s secrets and exits but will be very wary of exposure.', 'Rifts World Book 13: Lone Star p.121-122'),
('doctor-laura-cunningham', 'Doctor Laura Cunningham', 'Laura Cunningham', 'One of Bradford''s elite and super-secret scientists', 'rifts', 'Human', '12th level Cyber-Doc and Genetic Engineer', 12, 'Diabolic and insane', '45; looks 35', '5 feet, 7 inches (1.65 m)', '125 lbs. (56.2 kg)', '{"IQ":23,"ME":7,"MA":10,"PS":14,"PP":20,"PE":15,"PB":9,"Spd":21}', 69, 20, NULL, 11, NULL, NULL, NULL, '{"attacks":5,"strike":4,"parry":6,"dodge":6,"roll":2,"pull":2,"damage":2}', 'Hand to Hand: Basic, 9th level; damage bonus is S.D.C.; critical strike on 19-20; judo-style body throw/flip; +1 to save vs psionic attack. Horror/Awe Factor: not applicable.', '[{"name":"Language: American","pct":98},{"name":"Literacy: American","pct":98},{"name":"Criminal science & forensics","pct":98},{"name":"Medical doctor","pct":98},{"name":"M.D. in cybernetics","pct":98},{"name":"Pathology","pct":98},{"name":"Genetics (special)","pct":98},{"name":"Chemistry","pct":98},{"name":"Chemistry: analytical","pct":98},{"name":"Biology","pct":98},{"name":"Botany","pct":98},{"name":"Anthropology","pct":98},{"name":"Basic math","pct":98},{"name":"Advanced math","pct":98},{"name":"Computer operation","pct":98},{"name":"Computer programming","pct":98},{"name":"Pilot hovercraft (ground)","pct":98},{"name":"Pilot hovercycle","pct":98},{"name":"Radio: basic","pct":98}]', 'W.P. knife/surgeon skill at 12th level and W.P. energy rifle at 9th level.', NULL, 'None.', 'None.', NULL, 'Clock calendar; gyro-compass; universal headjack and ear implant', 'Access to all of GED including the secret area, with all the science, genetics and medical equipment and assistants she needs. Various surgical implements (scalpels, laser scalpel, etc.); frequently carries a Vibro-knife and Electro-Stun Prod. Almost never leaves the top secret level of GED.', '4.3 million in universal credits.', 'Intense and unnerving, forever weighing whoever is in front of her as a tool or a specimen. Consumed by her genetics and cloning work, she treats Bradford as a deity and has murdered to keep their secrets.', 'Doctor Desmond Bradford (trusted confidante; not controlled by implant or blackmail).', 'Anyone she suspects of threatening Bradford or the secret experiments. Scorns the Brigadier General and Colonel Collins.', 'A geneticist, surgeon and physician even madder than Bradford, specialising in rebuilding genes and splicing several species into one creature; she was central to making the Xiticix Killer. She would give her life for Bradford''s work, and anyone who takes it from her faces torture and use as an experimental subject instead of a quick death.', 'Rifts World Book 13: Lone Star p.123'),
('doctor-ammanda-santiago', 'Doctor Ammanda Santiago', 'Ammanda Maria Santiago', 'One of Bradford''s elite and super-secret scientists', 'rifts', 'Human', '10th level Medical Doctor/Psychologist and Genetic Engineer', 10, 'Miscreant', '41; looks 30', '5 feet, 6 inches (1.6 m)', '130 lbs. (58.5 kg)', '{"IQ":21,"ME":13,"MA":23,"PS":14,"PP":19,"PE":15,"PB":15,"Spd":12}', 51, 25, NULL, 5, NULL, NULL, NULL, '{"attacks":4,"initiative":3,"strike":3,"parry":5,"dodge":6,"roll":2,"pull":2,"damage":2}', 'Hand to Hand: Basic, 9th level; the initiative bonus comes from her bionic ear; damage bonus is S.D.C.; critical strike on 19-20; judo-style body throw/flip. Horror/Awe Factor: not applicable.', '[{"name":"Language: American","pct":98},{"name":"Literacy: American","pct":98},{"name":"Language: Spanish","pct":98},{"name":"Literacy: Spanish","pct":98},{"name":"Prowl","pct":72},{"name":"Streetwise","pct":59}]', 'All at around 92%: criminal science & forensics, medical doctor, pathology, genetics (special), psychology (special), chemistry, chemistry: analytical, biology, botany, anthropology, basic and advanced math, computer operation, computer programming, pilot hovercraft (ground), pilot hovercycle, pilot boat, radio: basic. W.P. knife (surgeon skill) and W.P. energy pistol, both at 9th level.', NULL, 'None.', 'None.', NULL, 'Clock calendar; gyro-compass; universal headjack and ear implant with amplified hearing', 'Access to all of GED including the secret area and cloning facilities, her own private lab (cloning facilities for eight individuals), and all the equipment and assistants she needs. Usually a laser scalpel in her boot (used as a weapon), and a Vibro-knife, Neuro-Mace and CP-30 laser pulse pistol on her belt. Duplicate files of every project she has worked on; a modest lab being built in the basement of her home in Arkansas. When traveling: a camouflage-painted CS "Skull" Patrol Car (200 M.D.C.) and an escort of six secret creations (one mutant chimpanzee, two mutant felines, three Dog Boys) with Triax and CS weapons, Triax body armor, and hovercycles (the page says two drive Turbo hovercycles, one an NG Stinger).', 'One million universal credits available at Lone Star, plus another 1.8 million credits, one million credits worth of pre-Rifts artifacts and tens of millions of credits worth of genetic research information in a secret hiding place (not her home).', 'Outwardly warm, soft-spoken and maternal, with a humor that can turn cruel. A flawless liar and performer who toys with people and gets her way by guile, not violence; she looks after herself first and would flee with whatever she could carry before dying for Bradford or the research.', 'Doctor Desmond Bradford (trusted associate); six secret mutant bodyguards unknown to the CS; the Cormack family and "Auntie Breann" (a very human-looking mutant Doberman) who raise two of the clones. Known as Patricia Lamanta at the mercenary outpost.', 'Bradford would be furious and might kill her and the clones if he learned of them.', 'A cloning, psychology and behavior specialist with an angelic manner and a murderous nature, currently refining personality modifier implants. She fools everyone, Bradford and Claval included. NOTE ON BRADFORD''S CLONES: without his knowledge she has cloned Desmond Bradford and placed the boys in different upbringings to see how each turns out and how several Bradfords might change the world. Five are described: the twins Karl and Desi Cormack (about 12 or 13, on a farm in southern Missouri), Brad Spartan (about 14 or 15, the oldest, training as a mercenary near the Arkansas-Missouri border), "Fast Ford" (12 or 13, a 3rd level City Rat thief and hacker in a southern Arkansas gang), and a 12 year old she raises as her own son in the same town. More may exist, though probably no more than a dozen in all. If exposed she would hide at least half of them, the son and the twins first.', 'Rifts World Book 13: Lone Star p.124-126'),
('gray-fox', 'Gray Fox', 'Yakima Gray Fox', 'Chief of the Apaches, the largest tribe in the Pecos Empire', 'rifts', 'Human', '14th level Wilderness Scout', 14, 'Scrupulous', '63', '5 feet, 8 inches (1.7 m)', '170 lbs. (77 kg)', '{"IQ":11,"ME":15,"MA":10,"PS":12,"PP":8,"PE":15,"PB":11,"Spd":11}', 64, 40, NULL, NULL, NULL, NULL, NULL, '{"attacks":6,"initiative":1,"strike":2,"parry":5,"dodge":5,"roll":2,"pull":2,"damage":3}', 'Hand to hand: expert. Pull/roll bonus applies to punch, fall or impact. Critical strike on 18-20; knockout/stun on 18-20; critical strike or knockout/stun from behind; judo-style body throw/flip; paired weapons.', '[{"name":"Speak Apache","pct":98},{"name":"Speak American","pct":98},{"name":"Speak Spanish","pct":98},{"name":"Literacy: American","pct":98},{"name":"Literacy: Spanish","pct":98},{"name":"History of the land (Lone Star)","pct":98},{"name":"Horsemanship","pct":98},{"name":"Land navigation","pct":98},{"name":"Wilderness survival","pct":98},{"name":"Cooking","pct":98},{"name":"Climbing","pct":98},{"name":"Identify plants","pct":98},{"name":"Fishing","pct":98},{"name":"Prowl","pct":98},{"name":"Track animals","pct":98},{"name":"Geomancy lore","pct":98}]', 'History of the land covers the last 300 years of Lone Star plus Apache stories and legends from before the Great Cataclysm, and rumors and legends of pre- and post-Rifts Earth. No % printed: hunting, athletics, W.P. knife, W.P. hunting rifle, W.P. energy rifle, W.P. archery. Hand to hand: expert.', NULL, 'None.', 'None.', NULL, NULL, 'CA-1 Dead Boy armor, old and damaged (57 M.D.C. remaining), worn only when he expects battle; Wilk''s 447 laser rifle; vibro-knife; conventional hunting rifle, bow and arrows, knife. His warriors carry modern Coalition and Northern Gun weapons and armor plus some magic talismans, charms and weapons; about 50% ride horses, the rest hovercycles (NG Speedster and Turbo especially).', 'Immediate access to several hundred thousand credits; several million more with Tribal Council approval.', 'A sober, fatherly elder who calls his tribe his children and steers them away from the warpath. Conservative and traditional, he acts as a brake on hot-headed younger leaders and is the first voice sought when the chiefs gather.', 'The Apache tribe (humans and D-Bees); adviser and mediator to over two dozen tribes, respected by Simvans and Psi-Stalkers; mutual respect with Sabre Lasar; admires Warlord Grange but worries about his aggression.', 'King Macklin respects only his reputation and regards him as a means to an end.', 'Grand old man of the Pecos Empire: a former tribal scout who rose by steadiness rather than brilliance, ruled the Empire for nearly two years during a plague and then stepped down of his own accord. Dark-eyed, with shoulder-length gray hair, in his early sixties.', 'Rifts World Book 13: Lone Star p.138-139'),
('king-macklin', 'King Macklin', 'Victor Macklin', 'King of the Kingdom of Worth; leader of the Pecos Raiders', 'rifts', 'Human', '10th level Pecos Raider/Mercenary Fighter', 10, 'Diabolic', '29', '5 feet, 11 inches (1.8 m)', '210 lbs. (95 kg)', '{"IQ":11,"ME":15,"MA":10,"PS":23,"PP":12,"PE":14,"PB":10,"Spd":15}', 51, 30, NULL, NULL, 51, NULL, NULL, '{"attacks":6,"initiative":1,"strike":2,"parry":4,"dodge":4,"roll":3,"pull":3,"damage":11}', 'Hand to hand: expert. The +11 damage is printed as S.D.C. damage. Pull/roll bonus applies to punch, fall or impact. Critical strike on 18-20; judo-style body throw/flip; paired weapons. Needs a 12 or higher to save vs psionic attack.', '[{"name":"Speak American","pct":98},{"name":"Speak Spanish","pct":98},{"name":"Literacy: American","pct":75},{"name":"Literacy: Spanish","pct":75},{"name":"Pilot motorcycle","pct":98},{"name":"Fishing","pct":95},{"name":"Horsemanship","pct":96},{"name":"Wilderness survival","pct":85},{"name":"Land navigation","pct":82},{"name":"Prowl","pct":85},{"name":"Palming","pct":80},{"name":"Identify plants","pct":80},{"name":"Track animals","pct":75}]', 'No % printed: athletics, sniper, hunting, W.P. sword, W.P. energy pistol, W.P. energy rifle, W.P. automatic pistol. Hand to hand: expert.', NULL, 'None.', 'Major psionic. Mind block; Empathy; Sixth sense; Clairvoyance; See the invisible; Bio-regenerate (self); Resist fatigue. I.S.P. 51.', NULL, NULL, 'Old-style SAMAS power armor (taken on a Lone Star raid); C-14 assault laser; C-18 laser pistol; vibro-saber; an array of other weapons.', 'Access to several million credits.', 'A paranoid schemer hungry for power who would rather have others fight for him. Deceit is his real weapon; cornered, he fights dirty, shows no mercy, and takes pleasure in tormenting people.', 'Henchmen of note: Matthew Brehan (renegade CS Major, diabolic 8th level RPA SAMAS pilot, old-style SAMAS with rail gun and particle beam rifle); Nick Bastone (7th level miscreant Juicer); Robert Bastone (5th level anarchist Juicer); Big Bob (6th level miscreant Mega-Juicer); Lord Faltennal (elf, 6th level anarchist Ley Line Walker). Average bandit under him is 3rd-6th level: 10% Juicers, 20% Headhunters, 20% Wilderness Scouts, 20% thieves/bandits, 3% Crazies, 4% ''Borgs, the rest vary. Rules about 3800 people. Secret CS contact ''Mr. Gene'' (Doctor Desmond Bradford, unknown to Macklin) hires his men for special jobs and feeds him inside information.', 'CS General Kashbrook is massing forces along the eastern border of the northern quadrant for an offensive against him and the Kingdom of Worth. Sabre Lasar, Don Marco and Gray Fox all see through him; the Sabre Warriors have won every skirmish against his gang.', 'His legend says he was a boy hostage whose family was betrayed and who avenged them at 16, becoming king at 18. In truth he volunteered as a hostage, planned the murder of his own father and brothers, then double-crossed his partners; his fame as a tactician rests on lopsided fights and tips from a Coalition contact. Dark-haired, with a goatee kept deliberately sinister.', 'Rifts World Book 13: Lone Star p.139-142'),
('orpheus-the-titan', 'Orpheus The Titan', 'Orpheus Stonewalker', 'Lord Mayor of Houstown', 'rifts', 'Palladium Titan', '9th level Warrior and Mystic', 9, 'Principled', '180', '13 feet (3.9 m)', '700 lbs. (317 kg)', '{"IQ":13,"ME":10,"MA":12,"PS":21,"PP":25,"PE":26,"PB":20,"Spd":12}', 55, NULL, 160, 141, 79, NULL, NULL, '{"attacks":7,"initiative":2,"strike":7,"parry":8,"dodge":8,"roll":3,"pull":3,"damage":6}', 'Hand to hand: martial arts. The block prints both Hit Points 55 and M.D.C. 160. Pull/roll bonus applies to fall or impact. +6 vs poison, +9 vs magic, +22% vs coma/death, 50% to charm/impress, +4 vs horror factor. Entangle; critical strike on 18-20; paired weapons; judo-style body throw/flip; jump kick; leap attack. +2 to spell strength (opponents need 14 or higher to save). Needs 10 or better to save vs psionics.', '[{"name":"Speak Elf/Dragonese","pct":98},{"name":"Speak Troll/Giant","pct":98},{"name":"Speak American","pct":98},{"name":"Literacy: Elf/Dragonese","pct":98},{"name":"Literacy: American","pct":80},{"name":"Dance","pct":90},{"name":"Monstermanship","pct":86},{"name":"Wilderness survival","pct":90},{"name":"Holistic medicine","pct":75},{"name":"Streetwise","pct":61},{"name":"Lore: demons/monsters","pct":75},{"name":"Sense supernatural evil","pct":95},{"name":"Open oneself to the supernatural","pct":95}]', 'No % printed: hunting, W.P. sword, W.P. knife, W.P. heavy, W.P. heavy energy weapons. Hand to hand: martial arts. Sense supernatural evil has a range of 390 ft (118.9 m); it and Open oneself to the supernatural are printed under Psionic Knowledge.', NULL, 'Globe of daylight; Climb; Concealment; Levitation; Mystic alarm; See aura; Thunderclap; Fingers of wind; Turn dead; Armor of Ithan; Charismatic aura; Resist fire; Trance; Cure minor disorders; Shadow meld; Superhuman strength; Superhuman speed; Cure illness; Tongues; Globe of silence; Invulnerability; Wisps of confusion; Oracle; Mute; Speed of the snail; Mystic portal; Control/enslave entity. +2 spell strength. P.P.E. 141.', 'Major psionic. Clairvoyance; Exorcism; Sixth sense; Astral projection; See the invisible; Sense magic; Induce sleep; Psychic purification; P.P.E. shield. Also Sense supernatural evil (390 ft/118.9 m) 95% and Open oneself to the supernatural 95%. I.S.P. 79.', NULL, NULL, 'Giant-sized chain armor (90 M.D.C.), a coming-of-age gift from his father; NG-202 rail gun; giant-sized Vibro-Sword (4D6 M.D.). Relies mainly on magic for protection.', 'Almost two million credits readily available; another 8 million with a few days notice.', 'Good-natured at heart but grown distant from the townsfolk he governs. He took the job because nobody else could do it as well, and tries to set a moral example that raider culture mostly finds too radical.', 'Gilgamesh the Wanderer and Endiku Longhair (Pantheons of the Megaverse p.62-65), who rescued him on arrival and remain firm friends; the people of Houstown.', NULL, 'A silver-haired giant from the Palladium world who stumbled through a Rift into a Federation of Magic battle, travelled south, and saved the coastal town of Houstown from Gulf sea monsters. Chosen as its mayor, he built it over a couple of decades into the most prosperous free city of the Pecos Empire.', 'Rifts World Book 13: Lone Star p.142'),
('zimchex', 'Zimchex', 'Zimchex', 'Chief of the Pervic Simvans of the Grande Range', 'rifts', 'D-Bee: Simvan', '8th level Simvan Monster Rider', 8, 'Unprincipled', NULL, '5 feet, 10 inches (1.79 m)', '180 lbs. (82 kg)', '{"IQ":12,"ME":15,"MA":6,"PS":15,"PP":18,"PE":23,"PB":7,"Spd":27}', 68, 108, NULL, NULL, 85, NULL, NULL, '{"attacks":7,"strike":4,"parry":6,"dodge":6,"roll":4,"pull":4}', 'Hand to hand: assassin. Pull/roll bonus applies to punch, fall or impact. +4 vs poison and magic, +16% vs coma/death. Knockout/stun on 17-20; entangle.', '[{"name":"Speak American","pct":85},{"name":"Literacy: American","pct":65},{"name":"Ride exotic animals (monsters)","pct":98},{"name":"Wilderness survival","pct":95},{"name":"Land navigation","pct":88},{"name":"Carpentry","pct":80},{"name":"Prowl","pct":80},{"name":"Identify plants","pct":80},{"name":"Radio: basic","pct":80},{"name":"Track humanoids","pct":80},{"name":"Track animals","pct":75},{"name":"Climbing","pct":75},{"name":"Faerie lore","pct":60}]', 'No % printed: athletics, body building, running, hunting, W.P. knife, W.P. energy pistol, W.P. energy rifle, W.P. archery & targeting, W.P. automatic rifle, W.P. blunt. Hand to hand: assassin.', 'Shares the Psi-Stalker style psychic rapport with animals (Rifts RPG p.106, item 8).', 'None.', 'Major psionic. Empathy; Telepathy; Sixth sense; Mind block; Mind bond (super); psychic affinity with animals like a Psi-Stalker''s. I.S.P. 85.', NULL, NULL, 'Lightweight Simvan body armor (45 M.D.C.); NG-L5 laser rifle; NG-33 laser pistol; vibro-knife; crossbow and arrows for vampires; Techno-Wizard six-shooter firing energy bolts (1D6 M.D. per blast; see Rifts New West); other conventional weapons.', 'Little ready cash (the tribe is mostly paid in barter, shared out among its members); in a pinch about 450,000 credits of cash and equipment at Black Market value.', 'A front-line fighter who relishes battle yet treats the chieftaincy as first among equals, hearing out his warriors and elders. Only his grudges against the Coalition and the Long Knives cloud his judgement; anyone fighting the CS is a friend.', 'The Pervic Tribe (all Simvan apart from 2-3% renegade CS mutant animals, mostly Dog Boys); Reid''s Rangers; likes most Tokanii and Psi-Stalkers; helps runaway CS mutant animals defect.', 'The Coalition, Lone Star above all (hit and run raids on troops south of Odessa); the Long Knives Tribe of Psi-Stalkers, a vendetta nearly four generations old; minor feuds with rival Simvan clans and Indian tribes.', 'Hereditary chief of a horse-trading, monster-taming Simvan tribe, raised to the post when Coalition troops shot his elder brother from behind on a peaceful trading trip near Fort El Dorado. Average build, with a scar down the left side of his face.', 'Rifts World Book 13: Lone Star p.143-144'),
('lianna-the-wild', 'Lianna The Wild', 'Lianna San Doria', 'Warlord of the She-Devils', 'rifts', 'Human', '9th level Gunslinger', 9, 'Aberrant', '28', '5 feet, 8 inches (1.7 m)', '110 lbs. (50 kg)', '{"IQ":14,"ME":12,"MA":13,"PS":11,"PP":21,"PE":17,"PB":15,"Spd":15}', 44, 39, NULL, NULL, 50, NULL, NULL, '{"attacks":6,"initiative":7,"strike":7,"parry":6,"dodge":6,"roll":3,"pull":3}', 'Hand to hand: martial arts. +1 attack when using handguns. Pull/roll bonus applies to punch, fall or impact. +1 vs poison and magic, +5% vs coma/death. Jump kick; entangle; leap attack; critical strike on 18-20; paired weapons.', '[{"name":"Speak American","pct":98},{"name":"Speak Spanish","pct":98},{"name":"Literacy: American","pct":85},{"name":"Literacy: Spanish","pct":85},{"name":"Horsemanship","pct":98},{"name":"Cooking","pct":80},{"name":"Pilot hovercraft","pct":82},{"name":"Wilderness survival","pct":80},{"name":"Land navigation","pct":78},{"name":"Prowl","pct":80},{"name":"Identify plants","pct":75},{"name":"Track animals","pct":70}]', 'No % printed: athletics, hunting, W.P. knife, W.P. energy pistol, W.P. energy rifle, W.P. automatic pistol. Hand to hand: martial arts.', NULL, 'None.', 'Minor psionic. Resist hunger; Resist thirst. I.S.P. 50.', NULL, NULL, 'Full environmental body armor, the best non-powered suit she can get (prefers Gladiator and Crusader); TX-43 laser assault rifle (3 settings: 6D6 S.D.C., 2D6 or 4D6 M.D.; 20 shots; 2000 ft/610 m); NG-56 ion pistol (2D6 M.D.); TX-5 pump pistol; pair of heavy Techno-Wizard six-shooters (2D6 M.D. per blast; see Rifts New West); vibro-knife; conventional weapons.', 'Usually carries around 2D4x10,000 credits in universal credits, gems and other items; emergency funds of another 270,000; as a last resort her men can chip in another hundred thousand.', 'Headstrong and improvisational: she hears advice, decides alone, and drops a failing plan without fuss. Gruff with her riders yet fiercely protective of them and of innocents, forbidding cruelty and leaving the poor enough to live on.', 'The She-Devils: 70 regulars plus 10-30 transients (70-100 riders at any time) and about 200 family members left behind; often split into groups of 10-20. 70% male; 19% wilderness scouts, 17% thieves, 14% bounty hunters, 12% Gunslingers, 10% Gunmen, 10% headhunters, the rest vary; 80% human, the rest Simvan, Psi-Stalkers and a few others; average 4th to 8th level. Favorite resting place is Houstown.', NULL, 'Daughter of a prominent border-village family, abducted at 17 by the raiders who sacked it and handed to their chief. She played along, learned to ride and shoot, then answered his open challenge and outdrew him, taking over the gang and renaming it. Dark shoulder-length hair; her exploits have inspired three largely fictional films.', 'Rifts World Book 13: Lone Star p.144-145'),
('sundance', 'Sundance', 'Harry Longabaugh', 'The Sundance Kid; leader of the (new) Wild Bunch Gang', 'rifts', 'Human from pre-Rifts Earth', '10th level Gunslinger', 10, 'Anarchist (with aberrant tendencies)', '40', '6 feet, 2 inches (1.9 m)', '195 lbs. (88 kg)', '{"IQ":13,"ME":15,"MA":19,"PS":14,"PP":22,"PE":16,"PB":15,"Spd":12}', 54, 31, NULL, NULL, NULL, NULL, NULL, '{"attacks":6,"initiative":6,"strike":6,"parry":7,"dodge":7,"roll":2,"pull":2,"damage":3}', 'Hand to hand: expert. One extra shooting attack when using a specific weapon of expertise. Pull/roll bonus applies to punch, fall or impact. Critical strike on 18-20; knockout/stun on 18-20; paired weapons; judo-style body throw/flip. Special bonuses for shooting (not itemised in the block).', '[{"name":"Speak American","pct":98},{"name":"Speak Spanish","pct":98},{"name":"Literacy: American","pct":75},{"name":"Literacy: Spanish","pct":65},{"name":"Horsemanship","pct":98},{"name":"Wilderness survival","pct":95},{"name":"Tracking","pct":90},{"name":"Gambling","pct":85},{"name":"Detect ambush","pct":85},{"name":"Land navigation","pct":72},{"name":"Pilot hovercraft","pct":75},{"name":"First aid","pct":65},{"name":"Radio: basic","pct":65}]', 'No % printed: hunting, athletics, W.P. revolver, W.P. bolt-action hunting rifle, W.P. energy pistol, W.P. energy rifle, W.P. sharpshooting: revolver, W.P. sharpshooting: hunting rifle, W.P. sharpshooting: energy pistol, W.P. sharpshooting: energy rifle, W.P. knife. Hand to hand: expert.', NULL, 'None.', 'None.', NULL, NULL, 'Dislikes armor; when he must, wears something light such as Plastic-Man or Huntsman. Usually carries a laser rifle, 1D4+1 hand grenades, 1D4 flares, a pair of laser pistols, his Colt .45 pistol (his favorite) and a vibro-knife; a pair of small Vibro-Blades (1D4 M.D.) hidden in his boot tips for a last-resort surprise attack; about a hundred silver bullets and a silver plated dagger for vampires.', 'Usually carries around 20,00 to 30,000 credits (first figure as printed) in cash, gems and other items; another 300,000 salted away. Standing offer of 50,000 credits for information leading him to Butch Cassidy.', 'Charming, quick-witted and sure of himself, a plain dealer who would sooner do the shooting than the deciding and often goes along with what his men suggest. He is convinced Butch Cassidy also survived and wants him found; vampires and the supernatural unnerve him.', 'The (new) Wild Bunch Gang, a raiding band some 500 strong.', 'The Coalition States, whose cargo transports he raids and who fear he could unite the Pecos outlaws; vampires, which he hates (he avoids the Mexican border).', 'The outlaw of the 19th century Wild West, carried by a river through a dimensional portal in Bolivia to Rifts Earth around 97 P.A.; it took him two years to reach Texas, and within six years he was famous again. Many doubt the story. A moustached man with long blond hair.', 'Rifts World Book 13: Lone Star p.145-147'),
('warlord-grange', 'Warlord Grange', 'Alien Grange', 'Commander of the Pecos Riders (Grange''s Riders)', 'rifts', NULL, '11th level Wilderness Scout', 11, 'Aberrant', '36', '6 feet, 1 inch (1.8 m)', '175 lbs. (79 kg)', '{"IQ":14,"ME":16,"MA":17,"PS":14,"PP":12,"PE":13,"PB":12,"Spd":12}', 54, 47, NULL, NULL, NULL, NULL, NULL, '{"attacks":5,"strike":2,"parry":3,"dodge":3,"damage":3}', 'Hand to hand: expert. Critical strike on 18-20; knockout/stun on 18-20; paired weapons.', '[{"name":"Horsemanship","pct":98},{"name":"Fishing","pct":98},{"name":"Climbing","pct":98},{"name":"Wilderness survival","pct":98},{"name":"Speak American","pct":98},{"name":"Speak Spanish","pct":98},{"name":"Speak Dragonese/Elf","pct":98},{"name":"Literacy: American","pct":95},{"name":"Literacy: Spanish","pct":95},{"name":"Land navigation","pct":96},{"name":"Identify plants","pct":95},{"name":"Cook","pct":90},{"name":"Prowl","pct":90},{"name":"Track animals","pct":90}]', 'No % printed: W.P. knife, W.P. sword, W.P. energy rifle, W.P. hunting rifle. Hand to hand: expert.', NULL, 'None.', 'None.', NULL, NULL, 'Huntsman armor for most situations; Crusader armor when he expects a battle; TX-11 laser rifle; vibro-sword. Has access to a number of other weapons and armors.', 'Can readily lay hands on 350,000 credits and triple that within 24 hours; larger amounts take longer.', 'Sees raiding as plain business and bears no grudge against victims who fight back, though breaking his private code makes it personal. A hands-on commander when he can be, he never stops second-guessing tradition in search of a better method.', 'The Pecos Riders: always personally commands 2D4x100 Riders (typically 2nd-5th level, humans and D-bees); core gang in the hundreds, swelling 30-50% with transients; 60% ride horses and other animals; home base is a small kingdom at Uvalde. Allied smaller bands would bring the total to 7000-11,000 warriors in time of need. Has fought alongside Sabre Lasar several times, with mutual respect; admired by Gray Fox.', 'Regards Sabre Lasar as his only true rival for rule of the Pecos Empire; makes some elder warlords nervous.', 'Empire-born outlaw who kept questioning his gang''s orders, was usually right, and left to found his own band, which his unorthodox tactics and gift for organisation grew into one of the largest in the region. A bearded man in his mid-thirties with short reddish-brown hair.', 'Rifts World Book 13: Lone Star p.147'),
('emperor-sabre-lasar', 'Emperor Sabre Lasar', NULL, 'Self-proclaimed Emperor and Supreme Leader of the Pecos Empire; Warlord of the Sabre Warriors', 'rifts', 'Fire Dragon (young adult), always disguised as a human', '10th level Line Walker/Dragon', 10, 'Aberrant', 'Appears to be in his early 40s (741 years old)', '6 feet, 8 inches (1.95 m) as a human', '20 tons as a dragon', '{"IQ":20,"ME":19,"MA":20,"PS":34,"PP":18,"PE":22,"PB":26,"Spd":90}', NULL, NULL, 3000, 600, 70, NULL, 16, '{"attacks":8,"initiative":3,"strike":6,"parry":5,"dodge":5,"roll":3,"pull":3}', 'Real name printed as Unknown; ''Sabre Lasar'' is his human identity. The true, dragon figures are stored: P.B. 26 (14 in human guise), Spd 90 running and 150 flying (20 is what he pretends as a human). Supernatural P.S. and P.E. Horror Factor/Awe 16 as a dragon (10 as a human). Pretends to be a mortal with about 80 hit points and 60 S.D.C.; true M.D.C. 3000, and a cover story of an Armor of Ithan medallion explains the extra 200-300 M.D.C. he is seen to absorb. Hand to hand: expert (or so he pretends). +3 on all saving throws; +6 to save vs horror factor. Full Fire Dragon stats: Rifts Conversion Book (One) p.121.', '[{"name":"Basic math","pct":98},{"name":"Advanced math","pct":98},{"name":"Literacy: American","pct":98},{"name":"Literacy: Spanish","pct":98},{"name":"Literacy: Dragonese/Elven","pct":98},{"name":"Speak American","pct":98},{"name":"Speak Spanish","pct":98},{"name":"Speak Dragonese/Elven","pct":98},{"name":"Speak Gobblely","pct":98},{"name":"Speak Euro","pct":98},{"name":"Demon & monster lore","pct":90},{"name":"Faerie lore","pct":40},{"name":"Basic electronics","pct":92},{"name":"Computer operation","pct":92},{"name":"Climb","pct":90},{"name":"Swim","pct":90},{"name":"Prowl","pct":80},{"name":"Palming","pct":75},{"name":"Pick pockets","pct":80},{"name":"Streetwise","pct":66},{"name":"Pilot hovervehicles","pct":90},{"name":"Demolitions","pct":90}]', 'Climb is printed 90%/80%. No % printed: demolitions: disposal, W.P. knife, W.P. sword, W.P. energy rifle, W.P. heavy (rail guns, plasma, etc.), paired weapons. Loves the fastest hovercycles. Hand to hand: expert, or so he pretends.', 'A dragon living permanently in human shape, with supernatural strength and endurance he passes off as merely exceptional. In true form he runs at 90, flies at 150 and breathes fire.', 'All wizard spells from levels 1-8, plus Mute; Water to wine; Mystic portal; Metamorphosis: superior; Anti-magic cloud; Remove curse; Summon fog; Time hole; Protection circle: superior. P.P.E. 600.', 'All sensitive and physical psionic abilities. I.S.P. 70.', NULL, 'None, ever.', 'Access to virtually any weapons and equipment he wants. Wears modified new style Dead Boy armor; typically wields both a C-29 Hellfire plasma cannon and a C-40R SAMAS rail gun, plus half a dozen plasma grenades and 2-4 type two or three fusion blocks. Rumored (falsely, his own cover story) to own a medallion that grants Armor of Ithan.', 'Easy access to a million universal credits; his army holds millions of credits of weapons and vehicles. A dragon''s hoard worth over 100 million credits (gems, gold, magic items, ancient artifacts; only a third in universal credits) is hidden in Big Bend.', 'Supremely confident and seemingly fearless, always fighting beside his troops. Ruthless toward those he despises yet bound by a personal code that makes him fair and sometimes merciful, and playful enough to laugh off insults; he wants to build a united, multi-racial kingdom rather than simply destroy the Coalition.', 'The Sabre Warriors: approximately 6000 (give or take 5%-10%; rarely below 5500, can swell by 50%); double when he calls on his allies, and 1D4+4 times in emergencies threatening the whole Pecos Empire. Largest force he has commanded: fifty thousand combat troops (support group approx. 260,000); has led six of nine such united campaigns. Race: 40% Human, 22% Psi-Stalkers, 14% Simvan, 16% other D-bees, 3% mutant animals, 5% supernatural and creatures of magic. Occupation: 23% Mercs/Grunts/fighters, 10% Headhunters/Partial Cyborgs, 7% Full Conversion ''Borgs, 8.5% Juicers, 5% Crazies, 10% Wilderness Scouts, 10.5% Thieves, 3% Operators, 0.5% Mind Melters, 2% other psychics, 3% Mystics, 3% Line Walkers, 1% Techno-Wizards, 0.5% Shifters, 2% other practitioners of magic, 6% other O.C.C.s and R.C.C.s, 5% supernatural; about 63% are trained warriors (74% counting thieves). Levels: men at arms and thieves 1D4+4 (6th average); practitioners of magic and most others 1D4+2 (4th average); leaders and experts 1D4 higher (typically 7th-10th). Alignment: 32% Miscreant, 24% Aberrant (54% of leaders), 13% Diabolic, 28% Anarchist, 3% other. Also: the Kingdom of Los Alamo, whose neutrality he is expected to acknowledge (Pecos Empire overview, printed 137); mutual respect with Gray Fox and Warlord Grange.', 'Warlord Don Marco (who hates him and suspects he is more than human); King Macklin, whom he mocks and whose gang his men have beaten in every skirmish; the Coalition States, which see him as the greatest threat among the Pecos bandits.', 'The most notorious and powerful bandit leader in the Pecos Empire, a gifted strategist whose legion has taken on towns and even a full CS armored division, and to whom smaller gangs turn in a crisis. Nobody knows that the big, muscular man with long reddish blond hair is a dragon. He treats his title of Emperor half as a joke and wholly as a goal.', 'Rifts World Book 13: Lone Star p.148-150'),
('warlord-don-marco', 'Warlord Don Marco', 'Lorenzo Don Marco', 'Leader of the Silver Dagger Gang; Mayor of his city (base in San Antonio)', 'rifts', NULL, '9th level Mind Melter', 9, 'Miscreant', '38', '6 feet (1.8 m)', '160 pounds (72 kg)', '{"IQ":15,"ME":21,"MA":20,"PS":17,"PP":19,"PE":12,"PB":9,"Spd":14}', 45, 28, NULL, 3, 231, NULL, 10, '{"attacks":6,"initiative":2,"strike":4,"parry":5,"dodge":5,"roll":3,"pull":3}', 'Hand to hand: assassin. +3 to save vs horror factor; +3 to save vs psionic attack; needs a 10 or higher to save vs psionic attacks.', '[{"name":"Basic math","pct":98},{"name":"Speak American","pct":98},{"name":"Speak Spanish","pct":98},{"name":"Literacy: American","pct":98},{"name":"Literacy: Spanish","pct":98},{"name":"Computer operation","pct":85},{"name":"Computer programming","pct":75},{"name":"Pick pockets","pct":70},{"name":"Streetwise","pct":57},{"name":"Pilot hover vehicles","pct":90},{"name":"Horsemanship","pct":77}]', 'No % printed: W.P. knife, W.P. energy rifle, paired weapons. Hand to hand: assassin.', NULL, 'None. P.P.E. 3.', 'All sensitive and physical psionic abilities, plus Detect psionics; Psychic diagnosis; Psychic surgery; Bio-regeneration (super); Bio-manipulation; Empathic transmission; Mind wipe; Hypnotic suggestion; Psi-sword; Psi-shield; Telekinesis (super); Telekinetic force field; Telemechanics. Favors telekinesis, e.g. hurling 2-5 of his Vibro-Blades at once from several angles; also uses ectoplasm with his blades. I.S.P. 231.', NULL, 'None.', 'Access to virtually any weapons and equipment he wants. Always armed with 4-6 Bowie-knife styled Vibro-Blades (2D4 M.D. each), a TX-5 pump pistol, and a Techno-Wizard sub-machinegun firing telekinetic rounds (1D6 M.D. per burst of six rounds; range 2000 ft/610 m; 8 I.S.P. per burst; payload 10 bursts for 80 I.S.P.). Wears modified new style Dead Boy armor in combat.', 'Easy access to 1D6x10 million universal credits at any time and ten times as much in manpower and resources; 36 million universal credits hidden away for early retirement.', 'A brilliant administrator with boundless ambition who prefers to work unseen, and resents that outsiders never credit him for it. Anger brings out a cruel streak, and he uses his mental powers to torment victims before killing them; his own men mostly obey out of fear.', 'The Silver Dagger Gang: approximately 1200 foot soldiers and another 3200 city operatives/hoods/crooks (give or take 10%-20%); double when he marshals all his forces. Race: 40% Human, 12% Psi-Stalkers, 4% Simvan, 40% other D-bees, 3% mutant animals, 1% supernatural and creatures of magic. Occupation: 20% Mercs/Grunts/fighters, 10% Headhunters/Partial Cyborgs, 5% Full Conversion ''Borgs, 5% Gunslingers, 3% Bounty Hunters, 2% Super Spies, 5% Juicers, 1% Crazies, 10% Wilderness Scouts, 10% Smugglers, 8% Thieves, 2% Forgers, 5% Operators, 1% Mind Melters, 1% Mystics, 3% Line Walkers, 1% Techno-Wizards, 1% other practitioners of magic, 6% other O.C.C.s and R.C.C.s, 1% supernatural. Levels: men of arms and thieves 1D4+4 (6th average); practitioners of magic and most others 1D4+2 (4th average); leaders and experts 1D4 higher (typically 7th-10th). Alignment: 42% Miscreant, 14% Aberrant, 15% Diabolic, 26% Anarchist, 3% other. The gang handles a full third of all stolen goods fenced in the Pecos Empire.', 'Sabre Lasar, his most hated rival (he knows Lasar is more than human but not what). The Coalition: General Kashbrook has planted a psychic CS agent among his top aides, plus two mutant canine spies, and plans to push him against Lasar and then assassinate him; Don Marco knows about all three spies. Displeased by Sabre Lasar''s understanding with Los Alamo, which cuts into his smuggling (Pecos Empire overview, printed 137).', 'A crime boss rather than a riding warlord: from a fixed city base he runs gambling, drugs, fencing, smuggling, gun-running, Juicer and bionics shops, protection rackets and the local police, so quietly that few realise one person is behind it all. Tall and thin, with shaggy brown hair and an unsettling stare.', 'Rifts World Book 13: Lone Star p.150-151');
