-- Rifts World Book 13: Lone Star - its bestiary and its notable NPCs.
-- 1 creatures (migration 074) and 28 notable NPCs (migration 072),
-- with their attacks in stat_attacks (migration 073).
--
-- One-off data script, run once per environment. NOT a migration.
--
--   node scripts/d1-apply.mjs --local apps/character-creator/db/add-lone-star-creatures-and-npcs.sql
--
-- Written by scripts/bestiary-sql.mjs from 4 worker file(s). Every
-- creature row passes creatureFormulaGaps, every value is printable ASCII,
-- and an 8-word shingle check of the prose fields against the book's cached text finds no copied run.





-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 1 creatures are in' AS assertion, count(*) AS got, 1 AS want
  FROM creatures WHERE slug IN ('xiticix-killer');
SELECT 'and 0 of them are playable' AS assertion, count(*) AS got, 0 AS want
  FROM creatures WHERE playable = 1 AND slug IN ('xiticix-killer');
SELECT 'all 28 notable NPCs are in' AS assertion, count(*) AS got, 28 AS want
  FROM notable_npcs WHERE slug IN ('desmond-bradford', 'general-loni-kashbrook', 'brigadier-general-ivan-kalpov', 'colonel-roger-collins', 'colonel-buck-murphy', 'major-winston-claval', 'thomas-bat-masterson', 'lt-rex-crackshot', 'sgt-robert-claw', 'corp-lady-ann', 'corp-big-bear', 'sgt-ears-rippley', 'corp-savage-mike', 'corp-raphael-ralphy-boy', 'mitch-mutant-rat', 'glitch-mutant-rat', 'doctor-frederick-alexander', 'doctor-laura-cunningham', 'doctor-ammanda-santiago', 'gray-fox', 'king-macklin', 'orpheus-the-titan', 'zimchex', 'lianna-the-wild', 'sundance', 'warlord-grange', 'emperor-sabre-lasar', 'warlord-don-marco');
SELECT 'the creatures carry 10 attacks' AS assertion, count(*) AS got, 10 AS want
  FROM stat_attacks WHERE owner_kind = 'creature' AND owner_slug IN ('xiticix-killer');
SELECT 'and the notables 44' AS assertion, count(*) AS got, 44 AS want
  FROM stat_attacks WHERE owner_kind = 'notable_npc' AND owner_slug IN ('desmond-bradford', 'general-loni-kashbrook', 'brigadier-general-ivan-kalpov', 'colonel-roger-collins', 'colonel-buck-murphy', 'major-winston-claval', 'thomas-bat-masterson', 'lt-rex-crackshot', 'sgt-robert-claw', 'corp-lady-ann', 'corp-big-bear', 'sgt-ears-rippley', 'corp-savage-mike', 'corp-raphael-ralphy-boy', 'mitch-mutant-rat', 'glitch-mutant-rat', 'doctor-frederick-alexander', 'doctor-laura-cunningham', 'doctor-ammanda-santiago', 'gray-fox', 'king-macklin', 'orpheus-the-titan', 'zimchex', 'lianna-the-wild', 'sundance', 'warlord-grange', 'emperor-sabre-lasar', 'warlord-don-marco');

